INSERT INTO "public"."repositories" VALUES ('6adf0fcb-f4b5-4124-b6a6-65a78721f19e', 'WJLGraph', 'Collaborative_-Filtering', 'WJLGraph/Collaborative_-Filtering', 'github_compatible', NULL, 'https://github.com/WJLGraph/Collaborative_-Filtering.git', NULL, 'managed', NULL, '【协同过滤推荐算法 | UserCF/ItemCF 实现】 搞定 UserCF+ItemCF 协同过滤推荐算法～ 数据集：（本人懒癌首选10标签/4w条）：https://tianchi.aliyun.com/dataset/216549 备选数据集（30 + 标签 / 10 万条）：https://tianchi.aliyun.com/dataset/215680 .核心：行为加权（pv/fav/cart/buy）→ 余弦相似度 → KNN 邻居 → Top-N → 离线评估，Precision 0.96 / 0.99、覆盖率 1.0，附 12 张可视化与双算法流程图，并落地「臻享云牧」云养殖平台。基于天池真实数据集。', 'main', 1147129569, '2026-11-18 16:32:14.021772+08', '2026-11-18 12:26:51.311584+08', '2026-11-18 20:41:56.092273+08');
INSERT INTO "public"."repositories" VALUES ('a77b231a-e5dd-41bf-8103-f6760fcf1d10', 'WJLGraph', 'informer-', 'WJLGraph/informer-', 'github', 'https://api.github.com', 'https://github.com/WJLGraph/informer-.git', NULL, 'managed', NULL, 'Informer2020 无阉割分步复现：官方 Jupyter 版拆解为 .py 工程，ProbSparse Attention + 生成式解码，ETTh1 滑窗预测（seq96 / label48 / pred24），「6 轮早停 vs 30 轮不早停」对照实验定量验证早停价值（测试 R² 0.77 vs 0.45），踩坑与调参笔记全程留痕。', 'main', 1136809189, '2026-11-18 13:24:55.291776+08', '2026-11-18 12:32:15.633401+08', '2026-11-18 20:36:12.291404+08');
INSERT INTO "public"."repositories" VALUES ('cc15ca55-b0db-474b-915f-d5c5d024c721', 'WJLGraph', 'Cloud_Farming_Platform', 'WJLGraph/Cloud_Farming_Platform', 'github', 'https://api.github.com', 'https://github.com/WJLGraph/Cloud_Farming_Platform.git', NULL, 'managed', NULL, '臻享云牧 · 面向畜禽云养殖场景的 B2C+B2B 双端平台：Vue2 + Element UI 前端，SpringBoot + MyBatis-Plus + Redis 后端，JWT + RSA + 动态路由三角色权限，集成协同过滤推荐 —— 登录后按浏览 / 收藏 / 加购 / 下单行为个性化推荐心仪动物。', 'main', 1239808075, '2026-11-18 19:43:29.060365+08', '2026-11-18 18:01:56.127761+08', '2026-11-18 20:28:04.118269+08');
